INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('9453ea71305ebdc7', 'act_313396960515158', '5b675cc2352e3911', 1, 1, 1, 'live', 'How long until he notices the Chunkman', 'She gives him the Brown Chunkman and times how long before he spots the burgers and hot dogs in the print. The viewer knows before he does, so they wait.', 'Couples. Wives and girlfriends buying for a golfer. Film it now so it is live by Nov 1.', 'Brown Chunkman, any Chunkman or Drinko polo', 'Gift prank', NULL, '["I just bought my husband a golf polo and I''m not telling him what''s on it.", "Okay, he thinks this is a normal brown polo.", "Let''s see how long it takes him to find the hot dogs."]', '[{"label": "Open · 0 to 3s", "text": "Her setup line to camera, the mailer in her hand or already on the table in front of him."}, {"label": "Middle", "text": "Hand it over. Stay on his face while he reads the print. Let him say whatever he actually says."}, {"label": "Close", "text": "The print filling the frame while he laughs. \"There it is.\" Text: Everyone agreed to be in this video."}]', 'How long until he notices. Then: there it is.', 'Film his real reaction once. Let him say what he actually says. She is in on the joke and consent is on screen.', 'Tell him beforehand. Script his line. Hold the polo up to the lens.', NULL, 'Him at the kitchen table or his desk, head down, tearing open the Grunk mailer. Her voice over it, phone in her hand.', '"Here, got you something." at 4 seconds. Then the slow noticing at 12 to 18 seconds: "nice polo", then "wait a second".', 'Bogey Bros'' number one ad for 192 days is a wife filming her husband find the joke in a print, and Grunk has never filmed it.', '[{"brand": "Bogey Bros", "what": "\"Let''s see how long it takes him to realize it.\" Steal the timing: nice, nice, wait a second.", "url": "https://app.tryatria.com/ad/m1859794814679897"}, {"brand": "Bad Birdie", "what": "Her hand resting on the polo on the bed, her voice over it. Steal the tactile open.", "url": "https://app.tryatria.com/ad/m1548498556597153"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e5c0eb705859bcd5', 'act_313396960515158', '84c9b63b121ea617', 1, 2, 2, 'live', 'Unbox it, then take it to the range', 'Open the fall drop on the kitchen counter, then cut to the range in it the same night. One cut fixes the video we keep getting: a polo held up at a wall.', 'Any creator with a range nearby. The weekend golfer who buys the new drop the day it lands.', 'The fall drop: Brown Chunkman, Espresso Martini, Bearly Sober, Closet Grunk', 'Unboxing', NULL, '["Fall drop came in. We''re going straight to the range.", "Didn''t even make it inside. Opening this in the car.", "New Grunk, new range session. Let''s go."]', '[{"label": "Open · 0 to 3s", "text": "The box opening, hands only. Pull the polo out so the print fills the frame. Say the opener."}, {"label": "Middle", "text": "Hard cut to the range or the first tee. Polo on, one swing, the ball goes wherever it goes."}, {"label": "Close", "text": "Close-up of the print and the Chunkman at the bay. Say the print name. Walk to the next ball."}]', 'Taking the new Grunk straight to the range', 'Show the shirt moving: a swing, a walk, the cart. Say the print name once.', 'Read the product description. Stay in one room. Hold the polo up at a wall.', NULL, 'Hands only, tearing the Grunk mailer open on the kitchen counter, or the box sitting on a range mat under the lights. No face yet.', 'The cut to the range at 5 seconds: same shirt, now on you, first swing. Then the print and the Chunkman logo up close at the bay.', 'Bad Birdie''s two newest rising ads are a box opened in a kitchen and a box opened on a range mat at night, and the location change at 5 seconds is what keeps people.', '[{"brand": "Bad Birdie", "what": "Box opened on a range mat at night, \"taking my new items to the range\". Steal the cut from box to bay.", "url": "https://app.tryatria.com/ad/m2116152639293586"}, {"brand": "Bad Birdie", "what": "Kitchen first look of a new drop, box under the arm. Steal the first-look energy, then leave the kitchen.", "url": "https://app.tryatria.com/ad/m937514819007024"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'c357c9cc209e8c59', 'act_313396960515158', 'e5c0eb705859bcd5', 'meta', '120242222297840115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120242222297840115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='e5c0eb705859bcd5' AND ad_id='120242222297840115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('bea6fa2ddb962812', 'act_313396960515158', '84c9b63b121ea617', 1, 3, 3, 'live', 'Chunkman hats are back', 'The Chunkman hats are back in stock, and the one creator video that worked for us was a hat video. Pull it on, show the inside, wear it somewhere real.', 'Any creator. Works for women creators too. The guy who already owns four Grunk hats.', 'Chunkman hats (back in stock), Tittees hat, Donde Esta La Cart Girl hat, rope hats', 'Hat reveal', NULL, '["They restocked the Chunkman hat. I grabbed two.", "This is the hat the cart girl asked about.", "Rope hat, flag patch, and it says golf is a drinking sport on the inside. Sold."]', '[{"label": "Open · 0 to 3s", "text": "The hat going on, both hands, look up. Say the opener."}, {"label": "Middle", "text": "Macro of the embroidery, the rope, the lining. Name the hat."}, {"label": "Close", "text": "Hat on at the course, the bar or the cart. Someone asks about it."}]', 'Back in stock. Then the hat name.', 'Name the hat. Show it on a head, never on a table. Tittees and cart girl hats are fine to film.', 'Talk about polos in a hat video. If it is a hat, sell the hat.', NULL, 'Both hands pulling the hat on, your face half hidden by the brim, then you look up at the lens.', 'Flip the hat to show the inside: the rope, the patch, the lining that says GOLF IS A DRINKING SPORT on the Tittees hat.', 'Our only creator win so far was Rudy''s Navy Open Hat video, and Bad Birdie''s cap-pulled-on opener runs on the same first second.', '[{"brand": "Bad Birdie", "what": "A cap pulled on with both hands, then \"Ladies, tap\". The first second is the hands.", "url": "https://app.tryatria.com/ad/m1394607206130813"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'b5e637724791452d', 'act_313396960515158', 'bea6fa2ddb962812', 'meta', '120250469342960115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120250469342960115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='bea6fa2ddb962812' AND ad_id='120250469342960115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('21f807def6ed10cc', 'act_313396960515158', '84c9b63b121ea617', 1, 4, 4, 'live', 'The Den Caddy rolls up to the first tee', 'Everyone else brings a bag. You roll a cooler bag up to the first tee, the group reacts, and the free polo comes out of it.', 'A foursome. The guy who hosts the round and buys the beer.', 'Den Caddy + free polo', 'Reaction', NULL, '["Nobody knew I was bringing this.", "Showed up with the Den Caddy and the guys lost it.", "It''s a bag, it''s a cooler, and it came with a free polo."]', '[{"label": "Open · 0 to 3s", "text": "The arrival, wide. The group turns. Get their real faces."}, {"label": "Middle", "text": "Open it: cans, cold. Hand a few out. The free polo comes out and a buddy holds it up."}, {"label": "Close", "text": "Cheers on the tee box, beer in hand, the caddy in the middle of the shot."}]', 'Den Caddy + free polo (confirm the free polo is live before filming)', 'Daylight, a real course, the group''s faces. Beer in hand only. Confirm the free polo is live on the site before filming.', 'Chug. Stack a dozen cans. Drive the cart with a beer in hand. Film the caddy with nobody around.', NULL, 'The Den Caddy coming into frame on the cart or over your shoulder, the group turning to look. Daylight, a real tee box.', 'Unzipping the cooler, cans inside, then a buddy pulls the free polo out and holds it up.', 'Our own 326 series, the Den Caddy on a misty fairway with the free polo, is a proven offer, and the dark poster version of the same offer lost, so daylight and a group is the shape.', '[{"brand": "Bogey Bros", "what": "Two guys in matching polos in a cart, one driving, filmed from the passenger seat. Steal the two-guys framing for the arrival.", "url": "https://app.tryatria.com/ad/m1228261266174271"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '775399b5e8425c70', 'act_313396960515158', '21f807def6ed10cc', 'meta', '120246364301250115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120246364301250115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='21f807def6ed10cc' AND ad_id='120246364301250115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a48a9995745acd44', 'act_313396960515158', '84c9b63b121ea617', 0, 0, 5, 'live', 'Espresso Martini at the turn', 'The polo is called Espresso Martini, so you order the drink. The shirt and the glass in one shot at the halfway house.', 'Any creator. The guy who treats the turn like happy hour.', 'Espresso Martini polo', 'On-course POV', NULL, '["The polo''s called Espresso Martini so this was mandatory.", "Nine holes down, one of these, nine to go.", "If the shirt''s named after a drink, you order the drink."]', '[{"label": "Open · 0 to 3s", "text": "The glass slides in, the print behind it. Say the opener."}, {"label": "Middle", "text": "Hold the drink next to the print. Close-up of the print, then the drink."}, {"label": "Close", "text": "Cheers to camera, one sip, walk back to the cart for the back nine."}]', 'Espresso Martini. The polo and the drink.', 'One drink, casual. Say the print name.', 'Anyone looking drunk. HYDR18 or hangover talk. A second round on camera.', NULL, 'A martini glass sliding into frame across the bar top, the print behind it. No face yet.', 'Pull back: the polo matches the drink. One sip, then the whole fit at the bar.', 'Breezy Golf built a whole brand on the drink that belongs to the group, and Bogey Bros'' cart shot shows two guys at the turn is enough of a scene.', '[{"brand": "Bogey Bros", "what": "Two guys in the cart, one line, no spec list. Steal the framing for the halfway house.", "url": "https://app.tryatria.com/ad/m1228261266174271"}, {"brand": "Breezy Golf", "what": "The Transfusion: a drink that belongs to the crew. Make the Espresso Martini yours.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('f8a50e50a91bda59', 'act_313396960515158', '84c9b63b121ea617', 0, 0, 6, 'live', 'Closet Grunk: the respectable one', 'The Closet Grunk button-down looks like a normal shirt from across the room. She approves, then she finds the Grunk label.', 'Couples. The guy whose partner vetoes the loud polo at dinner.', 'Closet Grunk button-downs', 'Skit', NULL, '["Finally, a shirt I can take him to my parents'' in.", "He says it''s a Grunk shirt. It looks like a normal shirt. Suspicious.", "Dress code says collared shirt. This is a collared shirt. Technically."]', '[{"label": "Open · 0 to 3s", "text": "The buttons, in the mirror, profile. Her voice off camera."}, {"label": "Middle", "text": "She nods from across the room. Then she walks over and turns the collar or finds the label. The Grunk logo up close."}, {"label": "Close", "text": "The two of them out the door. He winks. Text: Everyone agreed to be in this video."}]', 'The respectable side of Grunk Dolfer', 'Keep her genuinely pleased. The joke is that it is a Grunk shirt. She is in on it and consent is on screen.', 'Overexplain the camo. Let her be mean. Hold the shirt up to the lens.', NULL, 'Him doing up the buttons in the bathroom mirror, profile to camera, the tonal camo reading as plain.', 'Her line at 5 seconds: "Finally." Then she gets close and finds the Grunk logo on the collar or the label.', 'Bogey Bros'' rank-6 ad is a guy doing up a print polo in a bathroom with ''are you letting your man wear this to dinner'' over it, and it has run since March.', '[{"brand": "Bogey Bros", "what": "Doing up the buttons in the bathroom, \"Are you letting your man wear this polo to dinner?\". Steal the mirror open and her question.", "url": "https://app.tryatria.com/ad/m1447288833790481"}, {"brand": "Bogey Bros", "what": "\"Clean patterns that''ll pass a dress code.\" The range from respectable to loud as the pitch.", "url": "https://app.tryatria.com/ad/m1231852459066930"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('fb551e66ddae310f', 'act_313396960515158', '84c9b63b121ea617', 0, 0, 7, 'live', 'Fall scramble fit check', 'Head to toe walking off the first tee at a scramble or charity outing. Shoes up to the print, then the team steps in.', 'Any creator playing an outing this fall. Scramble teams.', 'Polos and hoodies', 'Fit check', NULL, '["Scramble fit check. Let''s go.", "Charity outing. 27 holes. One loud polo.", "Rate the fit, don''t rate the swing."]', '[{"label": "Open · 0 to 3s", "text": "The tilt, shoes to print. Say the opener."}, {"label": "Middle", "text": "The print up close, name it. Teammates step in one at a time."}, {"label": "Close", "text": "The four of you at the scramble sign or the first tee. Hoodie on if it is cold, polo under it."}]', 'Fit check. Then the print name.', 'Name the print. Show the group. Show both layers if you are wearing a hoodie.', 'Pose like a catalogue. Skip the print close-up.', NULL, 'Camera on your shoes on the tee box, tilting up the whole way to the print. Beer in the cup holder behind you.', 'A teammate steps into frame in a different print at 4 seconds. Then the other two.', 'Fit checks are the biggest format in golf TikTok right now, and Bad Birdie''s ''play 2 holes with me'' proves an invitation on the tee holds people.', '[{"brand": "Bad Birdie", "what": "A creator on the tee with a driver, \"Play 2 holes with me\". Steal the invitation, not the line.", "url": "https://app.tryatria.com/ad/m1623760625766692"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('4378e3727b104d65', 'act_313396960515158', '84c9b63b121ea617', 0, 0, 8, 'live', 'Going as a golfer for Halloween', 'Every guy at the party is Happy Gilmore. You go as a Grunk: a loud polo, a beer in hand and a terrible practice swing. Late October only.', 'Any creator with a party to go to. Film by Oct 24.', 'The Gilmore polo, Chunkman polos', 'Skit', NULL, '["Every guy at this party is Happy Gilmore. Be the one in the polo.", "Golf costume. Zero effort. One shirt.", "My wife said go as a golfer. This is a golfer."]', '[{"label": "Open · 0 to 3s", "text": "The two options held up. Say the opener. Choose the polo."}, {"label": "Middle", "text": "Walk into the party. Someone asks what you are. \"Golfer.\" A terrible practice swing in the kitchen, beer in the other hand."}, {"label": "Close", "text": "Close-up of the print. \"Best costume here.\" Posted by Oct 31."}]', 'Halloween, solved', 'Film by Oct 24. Post before Oct 31. Beer in hand, casual.', 'Use any film or Netflix imagery. Post it after Oct 31. Act drunk at the party.', NULL, 'A hockey jersey held up in one hand, The Gilmore polo in the other. Pick the polo.', 'The swap: jersey down, polo on, then you walk into a kitchen full of real costumes.', 'Every 2026 costume guide names the Happy Gilmore outfit as the default golf costume, so the room will already have three of them, and Grunk''s own Happy Gee line is the punchline.', '[{"brand": "Chubbies", "what": "Low-production pranks over glossy photography. A costume bit filmed on a phone at a real party.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('7e43522926032e83', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 9, 'live', 'The golfer who has everything', 'She flicks through twelve navy polos in his closet and lands on the one thing he does not own: a polo with a chubby guy holding a beer on it.', 'Wives, girlfriends, daughters and sons buying for the golfer who is hard to shop for.', 'Chunkman polos, any loud print, gift cards', 'Voiceover', NULL, '["He has every golf thing. He does not have this.", "Twelve navy polos. Twelve. Here''s number thirteen.", "Finally found something he didn''t have."]', '[{"label": "Open · 0 to 3s", "text": "The rail, the flick, the opener over it."}, {"label": "Middle", "text": "The Grunk print comes out. Hold it against the navy ones. The print up close."}, {"label": "Close", "text": "Him wearing it on a Saturday. \"He has not taken it off.\""}]', 'The one he''ll actually wear', 'A real closet. "Finally found something he didn''t have" is a real Grunk review, say it as is.', 'Any price or offer outside Black Friday week. Say anything about him you do not know is true.', NULL, 'A closet rail of navy and grey polos, her hand flicking through them fast. Her voice, no face yet.', 'The Grunk print appears at the end of the rail at 5 seconds. She pulls it out and holds it against the plain ones.', 'Bad Birdie''s rank-5 ad is her voice over his polos, and our own review card ''My old polos never left the closet again'' is one of our best stills.', '[{"brand": "Bad Birdie", "what": "\"He''s golfing all the time, he might as well be best dressed.\" Her voice, his polos, a hand on the fabric.", "url": "https://app.tryatria.com/ad/m1548498556597153"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'a78c64edae99e283', 'act_313396960515158', '7e43522926032e83', 'meta', '120249603609520115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120249603609520115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='7e43522926032e83' AND ad_id='120249603609520115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('9091b1574f8de8b2', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 10, 'live', 'Would you let your man wear this?', 'One question to women, with the loudest print as the answer. Ten seconds.', 'Women creators, or a couple. The partner who gets asked.', 'Drinko, Chunkman, Vegas Leopard, any loud print', 'Reaction', NULL, '["Would you let your man wear this to dinner?", "Be honest, is this a yes or a no?", "Girls, he wants this one. Verdict?"]', '[{"label": "Open · 0 to 3s", "text": "The macro, the question."}, {"label": "Middle", "text": "Pull back to the full print on him. His shrug."}, {"label": "Close", "text": "Her verdict, one word. Text: Everyone agreed to be in this video."}]', 'Would you let him?', 'Ask the question straight. She is in on the joke and consent is on screen.', 'Answer it yourself. Run past 12 seconds.', NULL, 'Macro of the collar and the placket, the print too close to read, then a pull back to the whole thing.', 'His face at 4 seconds: a shrug, a grin, nothing scripted.', 'Bogey Bros runs two ads on exactly this question (''would you let your man wear this polo?'') and both sit in their top ten.', '[{"brand": "Bogey Bros", "what": "Macro of the collar and placket, \"DON''T LET HIM WEAR THIS TO YOUR PARENT''S HOUSE\". Steal the macro open.", "url": "https://app.tryatria.com/ad/m1754504355696010"}, {"brand": "Bogey Bros", "what": "\"Are you letting your man wear this polo to dinner?\" as the whole ad.", "url": "https://app.tryatria.com/ad/m1447288833790481"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('c315794dcb90152c', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 11, 'live', 'The text from his girlfriend', 'One phone notification on a black screen, then the shirt in the exact place he was told not to wear it. Eight seconds.', 'Any creator with a partner who texts like this.', 'Any loud print', 'Screen record', NULL, '["DO NOT wear the beer shirt to my mom''s.", "You are not wearing that to the rehearsal dinner.", "Please tell me you packed a normal polo."]', '[{"label": "Open · 0 to 3s", "text": "The text on black. Nothing else. Three seconds."}, {"label": "Middle", "text": "Him in the shirt at the exact place. Beer in hand if it fits the room."}, {"label": "Close", "text": "Her face. Text: Everyone agreed to be in this video."}]', 'The text itself', 'One message, a real-sounding line, the shirt within 3 seconds. Treat it as a test.', 'A fake tweet, a fake review, a search bar. More than one message.', NULL, 'A black screen with one iMessage from Babe: DO NOT wear the beer shirt to my mom''s.', 'The cut at 3 seconds to him in the shirt at her mom''s table. Her face.', 'Bogey Bros'' rank-7 ad is a single text on black for ten seconds, but our own fake tweet and iMessage ads lost, so the line has to sound like a real person and the shirt has to land within 3 seconds.', '[{"brand": "Bogey Bros", "what": "A black screen, one text from \"Babe\", then the shirt. Ten seconds, rank 7.", "url": "https://app.tryatria.com/ad/m2115617322635468"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a3214d63b1777325', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 12, 'live', 'Dad and lil dude', 'Matching Chunkman polos on dad and the kid. The two shirts laid side by side first, then the kid walks out in his.', 'Dads who golf with their kid. Moms buying for both.', 'Kids polos + the matching adult print', 'Walkout', NULL, '["He wanted to match dad. Done.", "Kid size, dad size, same shirt.", "My son loves his kid sized shirts. He looks just like his dad on the golf course."]', '[{"label": "Open · 0 to 3s", "text": "The pair laid out. Say the opener."}, {"label": "Middle", "text": "The walkout, kid first, dad second. Both prints up close."}, {"label": "Close", "text": "The two of them on the putting green. A high five."}]', 'Matching dad and lil dudes', 'Consent for the kid. No face if the parent prefers. Check which kids prints are on the site before you film.', 'Beer anywhere in the kid''s shot.', NULL, 'Two polos laid side by side on the bed, one tiny. Same print.', 'The kid walking out of the bedroom in it at 4 seconds, then dad behind him in the big one.', 'Waggle''s gift reviews are full of parents buying one for every boy in the house, and nobody in loud golf is filming the matching walkout.', '[{"brand": "Waggle", "what": "Hat gift reviews: \"I got one for all these boys\". The gift is the matching, not the product.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('6437336c9467f109', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 13, 'live', 'Black Friday haul: BOGO + 30% off', 'The order that arrives after the deal, dumped out on the bed and counted. Film by Nov 10, post Nov 26 to 30 only.', 'The collector. The gift buyer who covered three people and kept two.', 'Everything (Black Friday)', 'Unboxing', NULL, '["Buy one get one and 30% off sitewide. So, yeah.", "This is what BOGO plus 30 looks like.", "Gifts for three people and two for me."]', '[{"label": "Open · 0 to 3s", "text": "The dump. Say the deal."}, {"label": "Middle", "text": "The count, print names as you go, who each one is for."}, {"label": "Close", "text": "The one you keep, on. Say the deal once more and that it ends Cyber Monday."}]', 'BOGO + 30% off sitewide (Black Friday videos only)', 'Say the deal exactly as it is on the site. Film by Nov 10. Post Nov 26 to 30.', 'Say the offer before Black Friday week or after Cyber Monday.', NULL, 'The box tipped out onto the bed, five polos sliding out at once.', 'Counting them out loud, one at a time, a number on screen for each. Then the one you keep.', 'Bad Birdie''s unboxings are their rising shape this fall, and Black Friday week is the biggest week we have.', '[{"brand": "Bad Birdie", "what": "A box opened on camera with the reveal as the rehook. Steal the shape, add the count.", "url": "https://app.tryatria.com/ad/m937514819007024"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('5b1d034433cc8dd9', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 14, 'live', 'The stocking stuffer drawer', 'Koozies, ball markers and hats, placed on the table one by one, fast. Nothing that needs a size.', 'Gift buyers filling stockings and secret santa.', 'Koozies, ball markers, hats, divot tools, towels', 'Flat lay', NULL, '["Stocking stuffers for the guy who golfs. Under forty bucks, all of it.", "Koozie, marker, hat. Done by Tuesday.", "He will not return any of this."]', '[{"label": "Open · 0 to 3s", "text": "The placing, fast, hands only."}, {"label": "Middle", "text": "Each item picked up for a second: what it does. The lining flip."}, {"label": "Close", "text": "The drawer or the stocking closing. Cut to him using the koozie on the cart."}]', 'Item names and prices from the site: koozies $9.95, ball markers $11.95, hats $39.95', 'Real prices from the site on the day. Tittees and cart girl hats are fine.', 'Anything that needs a size. Guess a price.', NULL, 'Hands placing items on a table one per beat: koozie, marker, hat, the Tittees hat.', 'The hat flipped to show the lining that says GOLF IS A DRINKING SPORT. Then the drawer closing.', 'Golf Course Prints has run gift ads for golfers since Oct 1, and small items with one job each is the shape the hat and koozie reviews already describe.', '[{"brand": "Golf Course Prints", "what": "\"Personalized Gifts For ANY Golfer\", live from Oct 1. The gift lane starts in October.", "url": "https://app.tryatria.com/ad/m1989979582389347"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('9456519012c481a6', 'act_313396960515158', '5b675cc2352e3911', 0, 0, 15, 'live', 'Christmas money, spent', 'Dec 26, the gift card goes on the new drop in eleven minutes. Screen record plus your face.', 'The collector who got a gift card. Dec 26 to Jan 5 only.', 'Gift cards, polos', 'Screen record', NULL, '["Got a Grunk gift card. It lasted eleven minutes.", "Christmas money. Gone. Worth it.", "The in-laws asked what I wanted. This."]', '[{"label": "Open · 0 to 3s", "text": "The card to camera. Say the opener."}, {"label": "Middle", "text": "Screen record: scroll, add to cart, one line on why each print."}, {"label": "Close", "text": "Checkout. Then the box arriving, as a follow-up."}]', 'Dec 26', 'Film Dec 26 to Jan 5. Hide the card number and balance.', 'Show a real card number. Post it before Christmas.', NULL, 'A Grunk gift card held up in front of the phone, the site already open behind it.', 'The cart total climbing as you add polos, then the checkout tap.', 'Our own December runs strong to Dec 31 on gift cards and Christmas money, and Hismile proved a promise of something shown later ("you''ll see the box arrive") holds people to the end.', '[{"brand": "Hismile", "what": "Promise something you will show later and say when, then show it. Here the promise is the box landing.", "url": "https://app.tryatria.com/ad/m1406603948018630"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('0528e111f44ee9b1', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 16, 'live', 'Rated for 19 holes', 'Hole 1 to the bar in one shirt, beer in hand at the turn and the end. Our best on-course footage says it in five words: most polos quit after 18.', 'Any creator with a real round to film. The Saturday group that ends at the bar.', 'Grunk Dolfer polos', 'On-course POV', NULL, '["Most polos quit after 18. This one''s rated for 19.", "One shirt, 18 holes, then the bar. Watch.", "We''ll see how it looks at the 19th."]', '[{"label": "Open · 0 to 3s", "text": "The tee shot from behind. Say the opener."}, {"label": "Middle", "text": "Real moments: a bad shot, a good one, the cart, the turn with a beer in hand. Text beats: 4-way stretch, moisture-wicking, breathable."}, {"label": "Close", "text": "The 19th hole. Everyone still looking good. Cheers to camera."}]', 'Rated for 19 holes', 'Real footage from a real round. Beer in hand, casual. The shakier the better.', 'Chug, shotgun, or drive the cart with a beer. Anyone looking drunk.', NULL, 'The first tee shot filmed from behind, the print filling the bottom of the frame, beer in the cup holder.', 'A cut to the halfway house at 5 seconds, can in hand. Then the bar at the end, still looking sharp.', 'Our own 337 C, real on-course footage of two guys drinking under MOST POLOS QUIT AFTER 18, is one of the cheapest sales we have ever bought.', '[{"brand": "Bogey Bros", "what": "Two guys in a cart, one line, no spec list. Steal the two-guys framing for the turn.", "url": "https://app.tryatria.com/ad/m1228261266174271"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '494f87bd2ce8f08d', 'act_313396960515158', '0528e111f44ee9b1', 'meta', '120249439447190115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120249439447190115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='0528e111f44ee9b1' AND ad_id='120249439447190115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('163c5eea81a414bb', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 17, 'live', 'The cart girl''s favourite foursome', 'The cart girl pulls up to four guys in Grunk and rates the shirts. She has the power in the clip and she is laughing with them.', 'A woman creator who works a cart or plays, and a foursome who agreed to be filmed.', 'Polos, Donde Esta La Cart Girl hat, Tittees hat', 'On-course POV', NULL, '["Pulled up to this group and had to film it.", "Okay, which one of you picked the shirts.", "Four for four. Finally."]', '[{"label": "Open · 0 to 3s", "text": "The roll-up from the cart. The four shirts."}, {"label": "Middle", "text": "Her ratings, one line each. The guys answer back. Beer in hand, nobody drunk."}, {"label": "Close", "text": "She drives off. Text on screen: Everyone agreed to be in this video."}]', 'Everyone agreed to be in this video', 'She is in on the joke and laughing with them. Consent on screen. Beer in hand only.', 'Anything that reads as hitting on her. Drunk golfers. Anyone driving the cart with a beer.', NULL, 'Filmed from the cart as it rolls up, four loud polos coming into frame one by one.', 'Her verdict on each shirt, fast, four in eight seconds. The Tittees hat gets a nod.', 'Cart girl POVs are the biggest driver in golf TikTok (Shay Patino, Cass Holland), and Good Good''s August ad showed what happens when the woman is the butt of the joke instead of in on it.', '[{"brand": "Cass Holland", "what": "Cart attendant videos captioned \"And then I drove away\" and \"Everyone agreed to be in this video\". She runs the clip.", "url": null}, {"brand": "Pins and Aces", "what": "The old winner: \"wearing our polos may cause compliments from the cart girl\". The compliment is the pitch.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('8ece9fc44fa64e97', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 18, 'live', 'Rate this polo at the 19th hole', 'Walk the bar after the round and ask strangers to rate the print 1 to 10. Keep the low scores, they are the rehook.', 'An outgoing creator. Anyone wondering if a loud polo is too much.', 'Grunk Dolfer polos', 'Street interview', NULL, '["Rate the shirt, one to ten, go.", "Asking the 19th hole what they think of the Drinko.", "Someone gave it a four. Watch what happens next."]', '[{"label": "Open · 0 to 3s", "text": "The first face, then the shirt. Say the opener."}, {"label": "Middle", "text": "Four to six answers, scores on screen. Keep the funny ones and the low one."}, {"label": "Close", "text": "The best quote. Someone asks where you got it. Print up close."}]', 'The scores', 'Consent from everyone filmed. Keep the real scores, even the low ones.', 'Script the answers. Film anyone who looks drunk.', NULL, 'A stranger''s face reacting before the camera shows the shirt.', 'Someone gives it a four at 5 seconds. The next person gives it a ten and asks where you got it.', 'Nobody in loud golf is doing bar interviews, and "where did you get that" is what our reviews say happens every round, so let strangers say it on camera.', '[{"brand": "Waggle", "what": "Review quote cards: \"Cart girls couldn''t stop complimenting\". Get the quote live instead of on a card.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('dc67b6e5550865fa', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 19, 'live', 'Hole 1 vs hole 18', 'The shirt at the start and at the end of a hot round, same pose, same angle. Sweat and all. Only say what the clip shows.', 'Any creator in a warm state. Guys who hate a sweaty, wrinkled shirt by the back nine.', 'Grunk Dolfer polos', 'Side by side', NULL, '["Hole one. Hole eighteen. Same shirt.", "Ninety-five degrees, four hours, moisture-wicking or whatever. See for yourself.", "Best shirt I own to beat the heat."]', '[{"label": "Open · 0 to 3s", "text": "The two stills side by side. Say the opener."}, {"label": "Middle", "text": "Honest checks: collar, back, sleeves. Beer in hand at the turn if there was one."}, {"label": "Close", "text": "Walk off the 18th green in it. Same shirt, same guy."}]', '1 / 18', 'Be honest. The shirt can look worn. Say the site claims only: moisture-wicking, breathable, 4-way stretch.', 'UPF, sun protection, stain-proof, beer-proof. Say it never shows sweat.', NULL, 'A split screen: hole 1 on the left, hole 18 on the right, same pose, the temperature on screen.', 'The pull back at 4 seconds: the hole 18 side is live, you are standing there, the shirt still looks like a shirt.', 'A before-and-after is the oldest proof shape there is, and ''best shirt I own to beat the heat'' is a real Grunk review, so the claim is already in a customer''s words. Drdent''s silent test is the model.', '[{"brand": "Drdent", "what": "Go quiet and let the camera watch the thing work, then react for real. Twenty silent seconds, then \"look at that\".", "url": "https://app.tryatria.com/ad/m1563635778876692"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('2d078b3e3ab002f0', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 20, 'live', 'How many beers fit in the Den Caddy', 'Fill the cooler on camera, one can per beat, and count. The number on screen climbs and the free polo comes out at the end.', 'Any creator with the Den Caddy. The guy who buys the beer for the group.', 'Den Caddy + free polo', 'Count demo', NULL, '["How many fit? Let''s find out.", "It''s a golf bag with a cooler in it. Counting.", "The guys asked. Here''s the answer."]', '[{"label": "Open · 0 to 3s", "text": "The empty cooler, the pile of cans, the first one in."}, {"label": "Middle", "text": "Loading, counting out loud, the number on screen each time."}, {"label": "Close", "text": "The last can, the total, the free polo out of the main pocket. Roll it onto the cart."}]', 'The running count. Den Caddy + free polo (confirm the free polo is live before filming)', 'Ice, real cans, an honest count. Confirm the free polo is live before filming.', 'Drink any of them on camera in this one. Say a number you did not count.', NULL, 'Cans going into the cooler pocket one at a time, a hand and ice, the count starting at 1 on screen.', 'The number keeps climbing. Then the free polo pulled from the main compartment at the end.', 'Waterboy''s best ad is a number said five times before the reveal, and our own 326 series proved the Den Caddy offer sells when it is shown plainly.', '[{"brand": "Waterboy", "what": "\"This has 3,100 milligrams\" five times, then the reveal. A number that keeps changing holds people.", "url": "https://app.tryatria.com/ad/m1616399766694709"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'd8d2fe82e44e6c2e', 'act_313396960515158', '2d078b3e3ab002f0', 'meta', '120246364301250115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120246364301250115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='2d078b3e3ab002f0' AND ad_id='120246364301250115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('79165dd43f5d0dff', 'act_313396960515158', 'e01f2d29a09a0b35', 0, 0, 21, 'live', 'The weekend golfer in the wild', 'A nature-documentary whisper over a guy in a Chunkman polo looking for his ball in the trees with a beer. Two or three lines, then he finds the wrong ball.', 'A creator with a buddy to narrate. Anyone who loves the parody.', 'Chunkman polos', 'Voiceover', NULL, '["Here we observe the weekend grunk in his natural habitat.", "Note the plumage. Loud, so the group can find him.", "He has not seen a fairway since the third."]', '[{"label": "Open · 0 to 3s", "text": "The trees, the long lens, the whisper."}, {"label": "Middle", "text": "He searches. He finds a ball. Holds it up. Wrong brand. Keeps it anyway."}, {"label": "Close", "text": "The walk back to the cart, beer still in hand. \"Remarkable.\""}]', 'The weekend grunk', 'Whisper it. Commit to the voice. Two or three lines is plenty.', 'Overwrite it. Act drunk. Borrow a catchphrase.', NULL, 'A long lens on a guy in the trees, the print visible through the branches, beer in his hand.', '"Here we see" at 3 seconds. Then he finds a ball. It is not his.', 'Bob Does Sports earned ''Bobby Fairways'' by hitting zero fairways in 36 holes, and FrontPorchDad built 900K followers saying things golfers actually say. Say those, not catchphrases.', '[{"brand": "Bob Does Sports", "what": "The nickname earned on camera, not written. Let the bit come from a real bad round.", "url": null}, {"brand": "FrontPorchDad", "what": "\"Stuff I hear people say a lot.\" The narration should be what your group already says about this guy.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('bd0c10988395b298', 'act_313396960515158', '6e3b5aca054d5842', 1, 5, 22, 'live', 'Small through 5XL on real bodies', 'Five guys, five sizes, one print, shoulder to shoulder. The camera walks the line and the 5XL guy turns. Nobody else in golf can film this honestly.', 'A crew of five. The big guy who has been burned by brands that stop at 3XL and run small.', 'Any polo that goes to 5XL (check the product page)', 'Fit check', NULL, '["Small through five X. Same shirt. Nobody''s squeezed into it.", "Every other brand stops at three X and runs small. We asked the big guys.", "I fit the chunk man description, so why not."]', '[{"label": "Open · 0 to 3s", "text": "The track down the line. Say the opener."}, {"label": "Middle", "text": "The turn. The biggest guy swings. Tucked and untucked both shown."}, {"label": "Close", "text": "The five of them walk to the first tee. Sizes over each man."}]', 'S / M / L / XL / 5XL over each man', 'Real sizes, real bodies. Say "relaxed, dad bod approved fit". Check 5XL is on that print before you film.', 'Name a competitor on screen. Say "slimming" or "athletic". Say every print comes in 5XL.', NULL, 'Five men shoulder to shoulder, the same loud print on all of them, the camera tracking left to right from the small guy.', 'The 5XL guy turns sideways at 5 seconds and the shirt still sits right over the belly.', 'Our own Tiktok #25 (''small through five'', ''dad bod approved'') is one of our best videos, and every competitor''s reviews say their polos run small.', '[{"brand": "Bad Birdie", "what": "The cinematic swing profile, no words. Steal the slow-mo swing for the biggest guy.", "url": "https://app.tryatria.com/ad/m2238178400364685"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '326df5aebe5e4e87', 'act_313396960515158', 'bd0c10988395b298', 'meta', '120244036055130115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120244036055130115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='bd0c10988395b298' AND ad_id='120244036055130115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('2be796f0bd908117', 'act_313396960515158', '6e3b5aca054d5842', 0, 0, 23, 'live', 'The full swing test', 'A full swing in slow motion in the relaxed cut. Nothing rides up, nothing pulls across the back. Claim only what the clip shows.', 'Any creator with a driver and a phone that does slow motion.', 'Grunk Dolfer polos', 'Fit check', NULL, '["Full send. Shirt stays put.", "Four-way stretch, allegedly. Testing.", "Watch the hem."]', '[{"label": "Open · 0 to 3s", "text": "The frozen backswing from behind. Say the opener."}, {"label": "Middle", "text": "Impact and finish, slow, from behind and then from the front."}, {"label": "Close", "text": "The ball goes wherever it goes. You laugh. The hem is still down."}]', 'Stays tucked (only if it does)', 'Tuck it, swing hard. Say the site claim: 4-way stretch.', 'Claim anything the clip does not show. Say it never comes untucked.', NULL, 'The top of the backswing frozen, the print stretched across your back, filmed from behind.', 'The follow-through at real speed, shirt still down. Then the same swing from the front.', 'Bad Birdie''s rising ad is a cinematic swing with no words at all, and the swing is the one moment where fit either works or it does not.', '[{"brand": "Bad Birdie", "what": "Swing follow-through in profile against blue sky, music only. Steal the shot, add the hem.", "url": "https://app.tryatria.com/ad/m2238178400364685"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('13f109092b81608b', 'act_313396960515158', '6e3b5aca054d5842', 0, 0, 24, 'live', 'I fit the Chunkman description', 'A guy with a belly talks to the mirror about why he stopped hiding it. The shirt is cut for him and it says so on the chest.', 'The Weekend Grunk. Guys with a beer belly who are done hiding it.', 'Chunkman polos', 'Fit check', NULL, '["Hides my beer belly. Gets compliments every round.", "I''m the guy on the shirt. Might as well wear the shirt.", "Great fit for a dude with a beer belly."]', '[{"label": "Open · 0 to 3s", "text": "The tilt, belly to face. Say the opener."}, {"label": "Middle", "text": "The side. The point: Chunkman, then you. Room to move."}, {"label": "Close", "text": "Out the door with the clubs. Beer in the cooler."}]', 'Dad bod approved', 'Deadpan. Proud. Say "relaxed, dad bod approved fit".', 'Self-pity. "Slimming" or "athletic". Sad music.', NULL, 'Belly first, filling the frame in the mirror, then the camera tilts up to your face.', 'You turn sideways at 4 seconds and the shirt hangs clean. Then you point at the Chunkman and at yourself.', 'Our own 284-1 callouts ("hides my beer belly", "gets compliments every round") outsold almost everything, and "great fit for a dude with a beer belly" is a real review.', '[{"brand": "Bogey Bros", "what": "The forced deadpan review: he side-eyes the lens and says one word. Steal the deadpan.", "url": "https://app.tryatria.com/ad/m919515360698444"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '6e4f79206da1e652', 'act_313396960515158', '13f109092b81608b', 'meta', '120237891762730115', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_313396960515158' AND ad_id='120237891762730115') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='13f109092b81608b' AND ad_id='120237891762730115');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('c3ceb0d1b5d3ddd8', 'act_313396960515158', '6e3b5aca054d5842', 0, 0, 25, 'live', 'Not for try-hards', 'Three reasons you should never buy Grunk Dolfer: you take golf seriously, you cannot take a joke, you own a swing trainer. A negative hook in a feed full of "you need this".', 'Any creator. The fun guy in the group self-selects.', 'Grunk Dolfer polos', 'Voiceover', NULL, '["Three reasons you should never buy this shirt.", "If you shoot 78 and sulk, this isn''t for you.", "Hardos, keep scrolling."]', '[{"label": "Open · 0 to 3s", "text": "The rail, the pan, the title on screen."}, {"label": "Middle", "text": "Three reasons, one print each, short."}, {"label": "Close", "text": "The Chunkman up close. \"Everyone else, this way.\""}]', 'The three reasons', 'Short reasons. Keep it under 20 seconds.', 'More than three. Name a competitor.', NULL, 'Polos hanging on a garage rail, the camera panning along them, text: 3 reasons you should NEVER buy Grunk Dolfer.', 'Reason one lands at 3 seconds with a print pulled off the rail. Two more, one print each.', 'Bogey Bros'' ''3 reasons why you should NEVER buy'' ad sits in their top 15 on nothing but a garage rail and a reverse list.', '[{"brand": "Bogey Bros", "what": "\"3 reasons why you should NEVER buy bogey bros\": polos on a garage rail, \"not for golf hardos, try-hards\". Steal the frame and the reverse list.", "url": "https://app.tryatria.com/ad/m2108429963090261"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('812fe3ae6187febf', 'act_313396960515158', '4e58ded985d926e8', 0, 0, 26, 'live', 'Nobody wants to draw this team', 'A scramble team walks in from the parking lot in four prints and the other teams look up. Banter between you, not to the camera.', 'A foursome. The Crew Captain who organises the scramble team.', 'Grunk Dolfer polos', 'Walkout', NULL, '["Who invited these guys.", "Scramble team''s here. Nobody''s winning long drive but we''re winning this.", "We can''t putt. Look at us though."]', '[{"label": "Open · 0 to 3s", "text": "The walk, wide. Film it twice, use the second take."}, {"label": "Middle", "text": "The stare from the next team. A quick real shot. A beer at the turn, in hand."}, {"label": "Close", "text": "The team photo in the prints at the first tee."}]', 'One subtitle line of banter', 'Film the walk twice. Say what your group actually says. Get the other team''s okay before you film them.', 'Look at the camera. Pose. Act drunk.', NULL, 'Four guys walking toward the camera from the parking lot, four prints, bags on shoulders, not looking at the lens.', 'One subtitled line from one of them at 3 seconds. Then a cut to another team staring.', 'birddogs'' number one ad right now is four guys walking a fairway with one subtitled line, and the foursome is the gap nobody in loud golf has filled.', '[{"brand": "birddogs", "what": "Four guys walking down a fairway laughing, one subtitled line, \"who invited the camera guy\". Steal the walk and the subtitle, not the line.", "url": "https://app.tryatria.com/ad/m1138217752221924"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('34e039abdccd4573', 'act_313396960515158', '4e58ded985d926e8', 0, 0, 27, 'live', 'The group chat picked the polos', 'Screen-record the chat arguing for three days over which prints to order for the trip, then cut to the four shirts on the hotel bed.', 'The Crew Captain planning the trip.', 'Grunk Dolfer polos', 'Screen record', NULL, '["The chat has been going for three days about shirts.", "Democracy picked the Drinko.", "Eight guys, one vote, no winners."]', '[{"label": "Open · 0 to 3s", "text": "The chat scroll. Say the opener."}, {"label": "Middle", "text": "The bed with the shirts laid out. The best line of the chat on screen."}, {"label": "Close", "text": "The group wearing them at the first tee of the trip."}]', 'The chat''s best line', 'A real chat with the names hidden.', 'A fake chat. Show real names or numbers.', NULL, 'A group chat scrolling fast, polo screenshots flying in, names hidden.', 'The cut at 5 seconds to the four shirts laid out on a hotel bed. Then the group in them.', 'Our biggest single orders are crews buying together, and Bogey Bros pitches its bundle straight at the group, so a real group chat is the most honest screen record there is.', '[{"brand": "Bogey Bros", "what": "Bundle tiers aimed at groups and the \"Field of 8\". The crew is the buyer.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('7fbd884ebedddca4', 'act_313396960515158', '4e58ded985d926e8', 0, 0, 28, 'live', 'Loser buys the polos', 'A two-man match, the loser buys the winner a polo. A count of holes on screen, the putt that decides it, the handover at the bar.', 'Two competitive buddies.', 'Grunk Dolfer polos', 'On-course POV', NULL, '["Loser buys the other guy a Grunk polo. Let''s go.", "Three holes, one shirt on the line.", "He''s never beaten me. Today he gets a polo."]', '[{"label": "Open · 0 to 3s", "text": "The handshake, the bet. Say the opener."}, {"label": "Middle", "text": "The count. Highlights and lowlights. The deciding putt."}, {"label": "Close", "text": "The handover at the bar, beer in hand. The loser puts it on."}]', 'The score', 'A real bet. Cut to the decider.', 'Run long. Chug at the bar.', NULL, 'Two guys shaking hands on the first tee. "Loser buys."', 'The hole count on screen climbing. The swing or putt that decides it.', 'Good Good Golf''s whole channel is stakes in the title, and a bet gives the viewer one thing to wait for.', '[{"brand": "Good Good Golf", "what": "Stakes in the title (\"Winner gets $1,000\"), a count, a decider. Steal the structure at 25 seconds.", "url": null}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('b630a6462c713342', 'act_313396960515158', '4e58ded985d926e8', 0, 0, 29, 'live', 'Field of 8: outfitting the guys'' trip', 'Eight guys, eight prints, stepping off the shuttle on the first morning of the trip. The slow pan down the line names every print.', 'The Crew Captain. Bachelor parties and guys'' trips.', 'Grunk Dolfer polos', 'Walkout', NULL, '["Eight guys. Eight shirts. One scramble nobody''s ready for.", "Bachelor party uniform, sorted.", "Scottsdale doesn''t know what''s coming."]', '[{"label": "Open · 0 to 3s", "text": "The step-off, wide. Say the opener."}, {"label": "Middle", "text": "The pan, print names on screen, one line of banter."}, {"label": "Close", "text": "The tee box, all eight, beer in hand for the ones who want one."}]', 'Print names, one per man', 'Shoot it on the first morning.', 'Show the night before. Anyone looking drunk.', NULL, 'Eight prints in a row stepping off a resort shuttle or out of a hotel elevator.', 'The slow pan down the line at 4 seconds, each print named on screen.', 'Bogey Bros sells its bundle as a ''Field of 8'' for bachelor parties, and our own biggest orders are crews buying eight at once.', '[{"brand": "Bogey Bros", "what": "The group bundle pitched as a \"Field of 8\" for bachelor parties and groomsmen. Steal the lineup.", "url": null}, {"brand": "birddogs", "what": "The foursome walk with banter. Make it eight.", "url": "https://app.tryatria.com/ad/m1138217752221924"}]');
