UPDATE p_amb_brand SET display_name='Grunk Dolfer', intro='Grunk Dolfer makes loud polos for guys who golf to hang out, not to grind. Golf is a drinking sport, so we want videos that look like a real Saturday: the crew, the cart, a beer in hand, the bad shots and the 19th hole. Your hands do something in the first second, film the group, and let the print do the joke. Pick one idea, do the first second the way it says, and submit it on TRYBE like always.', about='Loud, soft performance golf polos in prints you won''t see on anyone else, plus hats, hoodies, button-downs, koozies and the Den Caddy cooler bag. Relaxed, dad bod approved fit, small through 4XL on every polo and 5XL on many. The mascot is Chunkman, a chubby guy proudly holding a beer. New this fall: Brown Chunkman, Espresso Martini, Bearly Sober and the Closet Grunk button-downs. The Chunkman hats are back in stock.', audience='Weekend golfers, mostly guys 30 to 55, who play with the same three buddies, have a beer on the cart and care more about the day than the score. Plenty have a dad bod and own it. From late October we also talk to the wives, girlfriends and kids buying for the golfer who has everything, and to the guy ordering eight for the trip.', accent='#E05A25', avoid_json='[{"title": "Holding the polo up at the shop wall and talking", "why": "Every creator submission that lost looked exactly like this. Take it to the range, the cart, the bar or the kitchen table instead."}, {"title": "A hat video that talks about polos", "why": "Talk about the thing you are showing. If it is a hat, sell the hat. Our only creator win so far was a hat video that did."}, {"title": "Stiff, posed shots smiling at the camera", "why": "Our posed ads lose. Real rounds, real buddies and real reactions win."}, {"title": "Opening on another brand''s shirt", "why": "Keep the first second on Grunk. A plain unbranded polo is fine later, as the before."}, {"title": "Acting drunk or shouting at the lens", "why": "A beer in hand is the brand. Performing drunk is the try-hard tell, and it breaks ad rules. Say what golfers actually say."}, {"title": "Reading the product page out loud", "why": "Say one thing it does and show the rest. Nobody stops scrolling for a spec list."}, {"title": "Meme wrappers: fake tweets, fake reviews, search bars", "why": "Ours all lost. One real-sounding text from a real-sounding person is the only version worth testing."}]', rules_json='["Say what the site says about a polo: soft, moisture-wicking, 4-way stretch, breathable, wrinkle-resistant. The fit is \"relaxed, dad bod approved\". Never \"athletic\", never \"slimming\".", "Do not say UPF or sun protection about a polo. It is not confirmed. Never say stain-proof or beer-proof. Never say HYDR18 prevents or cures hangovers.", "Sizes: every polo comes small through 4XL, and many prints go to 5XL. Check the product page before you say 5XL.", "Beer in hand only. Nobody chugs, nobody looks drunk, and nobody drives a cart with a beer. Everyone with a drink on screen is 21 or older.", "Black Friday is BOGO + 30% off sitewide, said only in Black Friday videos (film by Nov 10, post Nov 26 to 30). Any other day: \"check the site for the current deal\".", "The Den Caddy comes with a free polo. Confirm the free polo is live on the site before filming.", "Any video with a woman in it: she is in on the joke, she has the power in the clip, and consent is on screen (\"Everyone agreed to be in this video\").", "Never name a competitor on screen. A plain unbranded polo as the before is fine.", "Show the print up close at least once and say the print''s name. Tittees and cart girl hats are fine to film.", "Film vertical, sound on. Only film people who agreed to be in your video, on a course that allows filming."]', season_json='{"title": "Fall drops, then gift season", "until": "Nov 25", "line": "The new drop is live from Oct 7 and the Chunkman hats are back in stock. Film your gift videos NOW so they are live by Nov 1. Black Friday week is the biggest week we have.", "next": "Black Friday: BOGO + 30% off sitewide, Nov 26 to 30", "highlight": ["10-06", "11-25"], "show_chart": true, "color": "#B45309", "cap": null, "mode": "custom", "custom": {"1": 20, "2": 20, "3": 25, "4": 26, "5": 34, "6": 36, "7": 38, "8": 32, "9": 30, "10": 30, "11": 33, "12": 32, "13": 34, "14": 50, "15": 38, "16": 28, "17": 27, "18": 27, "19": 28, "20": 33, "21": 34, "22": 36, "23": 44, "24": 55, "25": 42, "26": 36, "27": 34, "28": 25, "29": 24, "30": 23, "31": 24, "32": 24, "33": 23, "34": 18, "35": 17, "36": 15, "37": 14, "38": 15, "39": 18, "40": 30, "41": 32, "42": 28, "43": 22, "44": 22, "45": 28, "46": 32, "47": 45, "48": 100, "49": 55, "50": 65, "51": 64, "52": 55, "53": 40}}', guide_json='[{"title": "Your hands do something in the first second", "text": "Tearing the mailer, pulling the hat on, cans going into the cooler, buttons in the mirror. Then you can talk. Faces alone get scrolled. The best gift ad in golf opens on a bag being ripped open."}, {"title": "The print does the joke", "text": "You do not have to be funny. The burgers on the Brown Chunkman and the chubby guy with the beer are the joke. Get the print filling the frame and say what you would actually say: \"there it is\"."}, {"title": "Say who it is for in the first line", "text": "\"Big guys, this one''s for you.\" \"Girls, he wants this one.\" \"Scramble team''s here.\" The right person leans in and the wrong one leaves, and that is fine."}, {"title": "Change the picture at 3 seconds", "text": "Kitchen to range. Mailer to his face. Parking lot to the first tee. If you have been talking to the camera for 8 seconds without moving, cut."}, {"title": "Give them a count that climbs", "text": "Cans into the Den Caddy, holes in the match, polos out of the Black Friday box, seconds until he notices. If the viewer is waiting for one number, they stay."}, {"title": "Film the group", "text": "Four guys walking in from the parking lot is a top ad for another golf brand right now. The questions your buddies ask on camera are better than any line we write. Beer in hand, nobody drunk."}, {"title": "Let the wife film you", "text": "The number one ad in our category for 192 days is a woman with a phone timing how long until her husband notices the print. She is in on it, she runs the clip, and \"everyone agreed to be in this video\" is on screen."}, {"title": "End on the shirt being worn", "text": "On the tee, at the bar, walking out the door with the clubs. Say who it is for and what to do in your own words. No \"link below\", no wrap-up speech."}]', updated_at=datetime('now') WHERE act_id='act_313396960515158';
